def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--java", default="java")
    parser.add_argument("--javac", default="javac")
    args = parser.parse_args()
    production = ["src/main/java/gg/vape/module/combat/AutoMace.java",
                  "src/main/java/gg/vape/module/combat/HitSwap.java",
                  "src/main/java/gg/vape/module/combat/automace/AutoMaceAttackGate.java",
                  "src/main/java/gg/vape/module/combat/automace/AimSelectionRules.java",
                  "tools/tests/AutoMaceModuleTest.java"]
    with tempfile.TemporaryDirectory(prefix="vape-automace-test-") as temp:
        base = Path(temp)
        classes = base / "classes"
        classes.mkdir()
        sources = []
        for name, text in STUBS.items():
            path = base / "stubs" / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8")
            sources.append(str(path))
        subprocess.run([args.javac, "--release", "8", "-encoding", "UTF-8", "-d", str(classes)]
                       + sources + [str(ROOT / name) for name in production], cwd=ROOT, check=True)
        subprocess.run([args.java, "-cp", str(classes), "AutoMaceModuleTest"], cwd=ROOT, check=True)


if __name__ == "__main__":
    main()
